module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter D=0, E=1, F=2;

    always_comb begin
		case (state)
			D: next_state = (in1 || in2) ? F : E;
			E: next_state = (in1 || in2) ? D : F;
			F: next_state = (in1 || in2) ? E : D;
		endcase
    end

	assign out = (state==E);

endmodule

