            3'b010: out = 8'b11111011;
            3'b011: out = 8'b11110111;
            3'b100: out = 8'b11101111;
            3'b101: out = 8'b11011111;
            3'b110: out = 8'b10111111;
            3'b111: out = 8'b01111111;
            default: out = 8'b11111111;
        endcase
    end
