module counter7bit_carry (
    input clk,
    input rst,
    output reg [6:0] count,
    output reg carry_out
);always @(posedge clk or posedge rst) begin
    if (rst) begin
        count <= 7'b0000000;
        carry_out <= 0;
    end else if (count == 7'b1111111) begin
        count <= 7'b0000000;
        carry_out <= 1;
    end else begin
        count <= count + 1;
        carry_out <= 0;
    end
end

endmodule

