description:
Design a 3-to-8 line decoder that uses three input signals (A, B, C) to activate one of eight output lines (COUT) based on the binary value represented by these inputs. The module features an enable signal (EN) that controls whether the decoder is active; when EN is low, all output lines are set to high. When EN is high, the decoder outputs a low signal on the corresponding output line for the binary value determined by the combination of A, B, and C, while all other output lines are kept high. This design is useful for enabling specific device operations based on a binary selection input.
module top_module(
    EN,A,B,C,COUT
);

code:
module top_module(
    EN,A,B,C,COUT
);input EN,A,B,C;
    output[7:0] COUT;
    parameter s0 = 3'b000,s1= 3'b001,s2= 3'b010,s3 = 3'b011,
    s4 = 3'b100,s5 = 3'b101,s6 = 3'b110,s7 = 3'b111;
    reg[7:0] COUT;
    reg[2:0] ADR;
    always @(A,B,C,EN) begin
        ADR = {C,B,A};
        if(!EN) COUT <= 8'b11111111;
        else
            case(ADR)
                s0: COUT <= ~8'b11111110;
                s1: COUT <= ~8'b11111101;
                s2: COUT <= ~8'b11111011;
                s3: COUT <= ~8'b11110111;
                s4: COUT <= ~8'b11101111;
                s5: COUT <= ~8'b11011111;
                s6: COUT <= ~8'b10111111;
                s7: COUT <= ~8'b01111111;
					 default:COUT<=8'b11111111;
            endcase
    end 
endmodule

