module debounce(
    input clk,
    input rst_n,
    input btn_in,
    output reg btn_out
);

parameter STABLE_CYCLES = 10;
reg [3:0] counter;
reg btn_in_prev;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 0;
        btn_out <= 0;
        btn_in_prev <= btn_in;
    end else if (btn_in == btn_in_prev) begin
        if (counter < STABLE_CYCLES)
            counter <= counter + 1;
        else
            btn_out <= 1;
    end else begin
        counter <= 0;
        btn_out <= 0;
    end
    btn_in_prev <= btn_in;
end

endmodule

