module top_module(
    input A,
    input B,
    input C,
    input invert,
    output reg out
);reg mux_out;
reg inv_out;

always @ (posedge C) begin
    mux_out <= B;
    inv_out <= ~B;
end

always @ (posedge C) begin
    if (C == 1'b0) begin
        out <= A;
    end else begin
        if (invert == 1'b0) begin
            out <= mux_out;
        end else begin
            out <= inv_out;
        end
    end
end

endmodule

