module top_module(
  input clk,
  input reset,
  input [7:0] data_in,  // Changed to an 8-bit input to hold data
  output reg tx_out
);parameter IDLE_STATE = 1'b0;
  parameter DATA_STATE = 1'b1;

  reg [3:0] state;
  reg [3:0] count;

  always @(posedge clk or negedge reset) begin
    if(!reset) begin
      state <= IDLE_STATE;
      count <= 4'b0;
      tx_out <= 1'b1;
    end
    else begin
      case(state)
        IDLE_STATE: begin
          if(!data_in[0]) begin  // Use data_in[0] to detect start bit
            state <= DATA_STATE;
            count <= 4'b0;
            tx_out <= 1'b0;
          end
        end
        DATA_STATE: begin
          if(count == 4'b0000) begin
            tx_out <= 1'b0; // Start bit
          end
          else if(count < 4'b1000) begin
            tx_out <= data_in[count-1]; // Send actual data bits
          end
          else if(count == 4'b1000) begin
            tx_out <= 1'b1; // Stop bit
            state <= IDLE_STATE;
            count <= 4'b0;
          end
          count <= count + 1;
        end
      endcase
    end
  end

endmodule

