module top_module(
    input clk,
    input rstn,
    input wr_en,
    input rd_en,
    input [7:0] data_in,
    output reg [7:0] data_out,  // Change: declare data_out as reg
    output empty,
    output full
);reg [7:0] mem [31:0];
reg [4:0] write_ptr;
reg [4:0] read_ptr;
reg [4:0] count;

assign empty = (count == 0);
assign full = (count == 32);

always @(posedge clk or negedge rstn) begin
    if (~rstn) begin
        write_ptr <= 5'd0;
        read_ptr <= 5'd0;
        count <= 5'd0;
        data_out <= 8'd0; // Initialize data_out on reset
    end
    else begin
        if (wr_en && ~full) begin
            mem[write_ptr] <= data_in;
            write_ptr <= write_ptr + 1;
            count <= count + 1;
        end
        if (rd_en && ~empty) begin
            data_out <= mem[read_ptr];
            read_ptr <= read_ptr + 1;
            count <= count - 1;
        end
    end
end

endmodule

