module top_module(
    input a,
    input b,
    input reset,
    output reg final_output
);reg xor_output;
reg nor_output;

// XOR gate implementation
always @(*) begin
    if (a ^ b) begin
        xor_output = 1;
    end
    else begin
        xor_output = 0;
    end
end

// NOR gate implementation
wire nand1_output;
wire nand2_output;

assign nand1_output = ~(a & a);
assign nand2_output = ~(b & b);
assign nor_output = ~(nand1_output & nand2_output);

// Functional module implementation
always @(posedge reset) begin
    final_output <= 0;
end

always @(posedge nand1_output or posedge nand2_output) begin
    final_output <= xor_output | nor_output;
end

endmodule

module top_module(
    input in0,
    input in1,
    input in2,
    input [1:0] sel,
    input clr,
    input set,
    output reg out
);always @(*) begin
    case(sel)
        2'b00: out = in0;
        2'b01: out = in1;
        2'b10: out = in2;
        2'b11: out = 1'b0;
    endcase
end

always @(posedge set) begin
    out <= 1'b1;
end

always @(posedge clr) begin
    out <= 1'b0;
end

endmodule

