module mux4to1 
#(
parameter DATAWIDTH = 8
)
(
    input  [1:0]               sel,
    input  [DATAWIDTH-1:0]     in0,
    input  [DATAWIDTH-1:0]     in1,
    input  [DATAWIDTH-1:0]     in2,
    input  [DATAWIDTH-1:0]     in3,
    output reg [DATAWIDTH-1:0] out
);

always @(*)
begin
    case (sel)
        2'b00: out = in0;
        2'b01: out = in1;
        2'b10: out = in2;
        2'b11: out = in3;
        default: out = {DATAWIDTH{1'b0}};
    endcase
end

endmodule

module top_module(
    input clk, rst, if_id_write_en, pc_write,
    input [1:0] pc_source,
    input pstop_i,
    output i_read_en,
    output [31:0] i_addr,
    input [31:0] i_instr_in, jump_addr, branch_addr, reg_data_1,
    output reg [31:0] IF_ID_next_i_addr,
    output reg [31:0] IF_ID_instruction
);reg [31:0] pc_reg, pc_next;
    wire [31:0] next_i_addr;
    wire mem_op = (IF_ID_instruction[31:26] == 6'b100011) || (IF_ID_instruction[31:26] == 6'b101011);

    assign next_i_addr = pc_reg + 4;
    assign i_read_en = 1;
    assign i_addr = pc_reg >> 2;

    always @* begin
        pc_next = pc_reg;

        case (pc_source)
            2'b00: pc_next = next_i_addr;
            2'b01: pc_next = branch_addr;
            2'b10: pc_next = jump_addr;
            2'b11: pc_next = reg_data_1;
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            pc_reg <= 0;
        end else begin
            if (pc_write && !(pstop_i || mem_op)) begin
                pc_reg <= pc_next;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            IF_ID_next_i_addr <= 0;
            IF_ID_instruction <= 0;
        end else begin
            if (if_id_write_en) begin
                IF_ID_next_i_addr <= next_i_addr;
                IF_ID_instruction <= !(pstop_i || mem_op) ? i_instr_in : 0;
            end
        end
    end

endmodule

