module top_module(
  clock,
  resetn,
  enable,

  shift,
  incr_cntl,
  shift_in,
  incr_val,
  data_out,
  shift_out
);parameter COUNTER_WIDTH=64;
parameter INCREMENT_WIDTH=32;
parameter DAISY_WIDTH=64;

input clock;
input resetn;
input enable;

input shift;
input incr_cntl;
input [DAISY_WIDTH-1:0] shift_in;
input [INCREMENT_WIDTH-1:0] incr_val;

output [31:0] data_out;
output [DAISY_WIDTH-1:0] shift_out;

reg [COUNTER_WIDTH-1:0] counter;

always@(posedge clock or negedge resetn)
begin
  if( !resetn )
    counter <= { COUNTER_WIDTH{1'b0} };
  else if(shift) 
    counter <= {counter, shift_in};
  else if(enable && incr_cntl) 
    counter <= counter + incr_val;
end

assign data_out = counter;
assign shift_out = {counter, shift_in} >> COUNTER_WIDTH;

endmodule

module top_module(pc_next1,pc,Zero,O);input [63:0] pc_next1;
	input [63:0] pc;
	input Zero;
	output [63:0] O;

	reg [63:0] tmp;


	always @(*)
   begin
		case(Zero)
			1'b0:
				tmp = pc_next1;
			1'b1:
				tmp = pc;
		endcase
	end

	assign O = tmp;

endmodule

module top_module (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);
    // State encoding
localparam A = 2'b00;
localparam B = 2'b01;
localparam C = 2'b10;
localparam D = 2'b11;

always @(*) begin
    // Default output is 0, will update for specific states if needed
    out = 0;

    // State transition logic
    case(state)
        A: begin
            if (in == 1'b0)
                next_state = D;
            else
                next_state = C;
            out = 1;  // Output is 1 in state A
        end
        B: begin
            if (in == 1'b0)
                next_state = A;
            else
                next_state = B;
            out = 0;  // Output is 0 in state B
        end
        C: begin
            if (in == 1'b0)
                next_state = C;
            else
                next_state = D;
            out = 0;  // Output is 0 in state C
        end
        D: begin
            if (in == 1'b0)
                next_state = D;
            else
                next_state = C;
            out = 1;  // Output is 1 in state D
        end
        default: begin
            next_state = A;  // Default transition to state A if invalid state
            out = 0;
        end
    endcase
end

endmodule

