module top_module (
    input clk,
    input reset,
    input [7:0] d,
    output reg [7:0] q
);

    // 8-bit D flip-flop with synchronous reset logic
    always @(posedge clk) begin
        if (reset) begin
            q <= 8'b0;
        end else begin
            q <= d;
        end
    end

endmodule

