module top_module(
  input clk,
  input reset,
  input A,
  input B,
  input C,
  output reg match
);// Define states
  localparam IDLE = 2'b00;
  localparam S0 = 2'b01;
  localparam S1 = 2'b10;

  // Define inputs
  reg [1:0] state;
  reg [2:0] input_buffer;

  // State transition and output logic
  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      input_buffer <= 3'b0;
      match <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (A) begin
            input_buffer <= {input_buffer[1:0], A};
            state <= S0;
          end
        end
        S0: begin
          if (B) begin
            input_buffer <= {input_buffer[1:0], B};
            state <= S1;
          end else if (!A) begin
            input_buffer <= 3'b0;
            state <= IDLE;
          end
        end
        S1: begin
          if (C) begin
            input_buffer <= {input_buffer[1:0], C};
            state <= IDLE;
            match <= 1'b1;
          end else if (!B) begin
            input_buffer <= 3'b0;
            state <= IDLE;
          end
        end
      endcase
    end
  end
endmodule

