module top_module(
    i_data0,
    o_data0
);// Port mode declarations:
  input   [31:0] i_data0;
  output  [31:0] o_data0;

  //Multipliers:
  wire [31:0]
    w1,
    w4,
    w5,
    w4096,
    w4101,
    w160,
    w4261,
    w17044,
    w17043;

  assign w1 = i_data0;
  assign w4 = i_data0 << 2;
  assign w5 = i_data0 + w4;
  assign w4096 = i_data0 << 12;
  assign w4101 = w5 + w4096;
  assign w160 = w5 << 5;
  assign w4261 = w4101 + w160;
  assign w17044 = w4261 << 2;
  assign w17043 = w17044 - w1;

  assign o_data0 = w17043;

endmodule

